(
    ADF_LOADER_CONTROL_KEY NUMBER(38,0) NOT NULL,
    INSERT_DATETIME TIMESTAMP_TZ(9) NOT NULL DEFAULT CURRENT_TIMESTAMP(), 
    SRC_SCHEMA VARCHAR, 
    SRC_TABLE VARCHAR, 
