MERGE INTO UTIL.ADF_LOADER_CONTROL AS TGT
USING (SELECT ADF_LOADER_CONTROL_KEY, SRC_SCHEMA, SRC_TABLE, CUSTOM_QUERY
	FROM UTIL.TMP_ADF_LOADER_CONTROL
	MINUS 
	SELECT ADF_LOADER_CONTROL_KEY, SRC_SCHEMA, SRC_TABLE, CUSTOM_QUERY
	FROM UTIL.ADF_LOADER_CONTROL
	) AS SRC
ON TGT.ADF_LOADER_CONTROL_KEY = SRC.ADF_LOADER_CONTROL_KEY
WHEN MATCHED 
THEN UPDATE
	SET TGT.SRC_SCHEMA = SRC.SRC_SCHEMA
	,TGT.SRC_TABLE = SRC.SRC_TABLE
    ,TGT.CUSTOM_QUERY = SRC.CUSTOM_QUERY
WHEN NOT MATCHED 
THEN INSERT
	(ADF_LOADER_CONTROL_KEY
	,SRC_SCHEMA
	,SRC_TABLE
    ,CUSTOM_QUERY
	)
VALUES
	(
	SRC.ADF_LOADER_CONTROL_KEY
	,SRC.SRC_SCHEMA
	,SRC.SRC_TABLE
    ,SRC.CUSTOM_QUERY
	);
	
--Flip the minus and delete from the target
DELETE FROM UTIL.ADF_LOADER_CONTROL TGT
USING
(SELECT ADF_LOADER_CONTROL_KEY, SRC_SCHEMA, SRC_TABLE, CUSTOM_QUERY
	FROM UTIL.ADF_LOADER_CONTROL
	MINUS 
	SELECT ADF_LOADER_CONTROL_KEY, SRC_SCHEMA, SRC_TABLE, CUSTOM_QUERY
	FROM UTIL.TMP_ADF_LOADER_CONTROL
	) SRC
WHERE TGT.ADF_LOADER_CONTROL_KEY = SRC.ADF_LOADER_CONTROL_KEY;